"use client"

import { useCallback, useEffect, useRef } from "react"
import gsap from "gsap"
import { ScrollTrigger } from "gsap/ScrollTrigger"
import { useGSAP } from "@gsap/react"
import "./styles.css"

gsap.registerPlugin(ScrollTrigger)

const DEMO_FRAMES = Array.from(
  { length: 60 },
  (_, i) =>
    `https://picsum.photos/seed/frame${String(i).padStart(3, "0")}/1920/1080`,
)

export interface ScrollFrameCanvasProps {
  frameUrls?: string[]
  headerText?: string
  dashboardImage?: string
  className?: string
}

export function ScrollFrameCanvas({
  frameUrls = DEMO_FRAMES,
  headerText = "One unified workspace to build, test, and ship AI faster",
  dashboardImage,
  className,
}: ScrollFrameCanvasProps) {
  const container = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const imagesRef = useRef<HTMLImageElement[]>([])
  const frameRef = useRef({ frame: 0 })
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null)

  const render = useCallback(() => {
    const ctx = ctxRef.current
    const canvas = canvasRef.current
    if (!(ctx && canvas)) {
      return
    }

    const w = window.innerWidth
    const h = window.innerHeight
    ctx.clearRect(0, 0, w, h)

    const img = imagesRef.current[frameRef.current.frame]
    if (!(img?.complete && img.naturalWidth > 0)) {
      return
    }

    const imgAspect = img.naturalWidth / img.naturalHeight
    const canvasAspect = w / h
    let dw: number
    let dh: number
    let dx: number
    let dy: number

    if (imgAspect > canvasAspect) {
      dh = h
      dw = dh * imgAspect
      dx = (w - dw) / 2
      dy = 0
    } else {
      dw = w
      dh = dw / imgAspect
      dx = 0
      dy = (h - dh) / 2
    }

    ctx.drawImage(img, dx, dy, dw, dh)
  }, [])

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) {
      return
    }
    const dpr = window.devicePixelRatio || 1
    canvas.width = window.innerWidth * dpr
    canvas.height = window.innerHeight * dpr
    canvas.style.width = `${window.innerWidth}px`
    canvas.style.height = `${window.innerHeight}px`
    const ctx = canvas.getContext("2d")
    if (ctx) {
      ctx.scale(dpr, dpr)
      ctxRef.current = ctx
    }

    let loaded = 0
    const total = frameUrls.length
    imagesRef.current = frameUrls.map((url) => {
      const img = new Image()
      img.onload = () => {
        loaded++
        if (loaded === total) {
          render()
        }
      }
      img.onerror = () => {
        loaded++
      }
      img.src = url
      return img
    })

    const onResize = () => {
      const r = window.devicePixelRatio || 1
      canvas.width = window.innerWidth * r
      canvas.height = window.innerHeight * r
      canvas.style.width = `${window.innerWidth}px`
      canvas.style.height = `${window.innerHeight}px`
      const c = canvas.getContext("2d")
      if (c) {
        c.scale(r, r)
        ctxRef.current = c
      }
      render()
      ScrollTrigger.refresh()
    }
    window.addEventListener("resize", onResize)
    return () => window.removeEventListener("resize", onResize)
  }, [frameUrls, render])

  useGSAP(
    () => {
      const prefersReduced = window.matchMedia(
        "(prefers-reduced-motion: reduce)"
      ).matches
      if (prefersReduced) {
        return
      }

      const frameCount = frameUrls.length

      ScrollTrigger.create({
        trigger: ".sfc-hero",
        start: "top top",
        end: `+=${window.innerHeight * 7}px`,
        pin: true,
        pinSpacing: true,
        scrub: 1,
        onUpdate: (self) => {
          const progress = self.progress
          const animProgress = Math.min(progress / 0.9, 1)
          frameRef.current.frame = Math.round(
            animProgress * (frameCount - 1)
          )
          render()

          if (progress <= 0.25) {
            const zProg = progress / 0.25
            const tz = zProg * -500
            let opacity = 1
            if (progress >= 0.2) {
              opacity = 1 - Math.min((progress - 0.2) / 0.05, 1)
            }
            gsap.set(".sfc-header", {
              transform: `translate(-50%, -50%) translateZ(${tz}px)`,
              opacity,
            })
          } else {
            gsap.set(".sfc-header", { opacity: 0 })
          }

          if (dashboardImage) {
            if (progress < 0.6) {
              gsap.set(".sfc-hero-img", {
                transform: "translateZ(1000px)",
                opacity: 0,
              })
            } else if (progress <= 0.9) {
              const ip = (progress - 0.6) / 0.3
              const tz = 1000 - ip * 1000
              const op = progress <= 0.8 ? (progress - 0.6) / 0.2 : 1
              gsap.set(".sfc-hero-img", {
                transform: `translateZ(${tz}px)`,
                opacity: op,
              })
            } else {
              gsap.set(".sfc-hero-img", {
                transform: "translateZ(0px)",
                opacity: 1,
              })
            }
          }
        },
      })
    },
    { scope: container, dependencies: [frameUrls.length, dashboardImage] }
  )

  return (
    <div className={`sfc-container ${className ?? ""}`.trim()} ref={container}>
      <section className="sfc-hero">
        <canvas ref={canvasRef} className="sfc-canvas" />

        <div className="sfc-hero-content">
          <div className="sfc-header">
            <h1>{headerText}</h1>
          </div>
        </div>

        {dashboardImage && (
          <div className="sfc-hero-img-container">
            <div className="sfc-hero-img">
              <img src={dashboardImage} alt="" />
            </div>
          </div>
        )}
      </section>
    </div>
  )
}

export default ScrollFrameCanvas

.sfc-container {
  position: relative;
  width: 100%;
}

.sfc-hero {
  position: relative;
  width: 100%;
  height: 100svh;
  overflow: hidden;
}

.sfc-canvas {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sfc-hero-content {
  position: absolute;
  top: 25%;
  left: 50%;
  transform: translateX(-50%);
  transform-style: preserve-3d;
  perspective: 1000px;
  padding: 0.5rem 0;
}

.sfc-header {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 100vw;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  text-align: center;
  color: var(--sfc-fg, #241910);
  transform-origin: center;
  will-change: transform, opacity;
}

.sfc-header h1 {
  width: 50%;
  font-size: 3rem;
  font-weight: 400;
  line-height: 1.1;
}

.sfc-hero-img-container {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 50%;
  transform-style: preserve-3d;
  perspective: 1000px;
}

.sfc-hero-img {
  position: relative;
  width: 100%;
  height: 100%;
  transform: translateZ(1000px);
  opacity: 0;
  will-change: transform, opacity;
}

.sfc-hero-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

@media (max-width: 1000px) {
  .sfc-header h1 {
    font-size: 2rem;
  }

  .sfc-header h1,
  .sfc-hero-img-container {
    width: calc(100% - 4rem);
  }
}
